function LegislativeConfigPanel({ camaraId, canConfigure, actorContext, councilors, onTypesChange, onFeedback }) {
  const [config, setConfig] = useState(DEFAULT_LEGISLATIVE_CONFIGURATION);
  const [types, setTypes] = useState('');
  const [memberId, setMemberId] = useState('');
  const [boardRole, setBoardRole] = useState('Presidente');
  const [permissions, setPermissions] = useState([]);
  useEffect(() => {
    if (!camaraId) return undefined;
    return onSnapshot(doc(firestore, LEGISLATIVE_COLLECTIONS.settings, camaraId), snapshot => {
      const next = { ...DEFAULT_LEGISLATIVE_CONFIGURATION, ...(snapshot.data() || {}) };
      setConfig(next); setTypes((next.propositionTypes || []).join('\n')); onTypesChange(next.propositionTypes || []);
    }, error => onFeedback(error.message));
  }, [camaraId, onFeedback, onTypesChange]);
  const save = async event => {
    event.preventDefault();
    const propositionTypes = types.split('\n').map(value => value.trim()).filter(Boolean);
    try { const nextConfig = { ...config, propositionTypes, updatedAt: serverTimestamp(), updatedBy: actorContext?.userId || '' }; await setDoc(doc(firestore, LEGISLATIVE_COLLECTIONS.settings, camaraId), nextConfig, { merge: true }); await Promise.all((nextConfig.boardAssignments || []).map(item => updateDoc(doc(firestore, 'users', item.userId), { legislativePermissions: item.permissions || [], mesaPosition: item.role || '', updatedAt: serverTimestamp() }))); onTypesChange(propositionTypes); onFeedback('Mesa diretora, funções e acessos legislativos salvos.'); } catch (error) { onFeedback(error.message); }
  };
  const assignBoardRole = () => { if (!memberId) return; const person = councilors.find(item => item.id === memberId); const boardAssignments = [...(config.boardAssignments || []).filter(item => item.userId !== memberId && item.role !== boardRole), { userId: memberId, name: person?.name || person?.nome || person?.email || 'Vereador(a)', role: boardRole, permissions }]; setConfig({ ...config, boardAssignments }); setMemberId(''); setPermissions([]); };
  const removeBoardRole = userId => setConfig({ ...config, boardAssignments: (config.boardAssignments || []).filter(item => item.userId !== userId) });
  const permissionOptions = [['legislative.secretariat', 'Protocolar e tramitar'], ['legislative.minutes', 'Cadastrar atas'], ['legislative.presidency', 'Despachos e plenário'], ['legislative.commissionPresident', 'Presidir comissão e designar relator'], ['legislative.rapporteur', 'Emitir parecer de relatoria'], ['legislative.legalOpinion', 'Emitir parecer jurídico']];
  return <form className="legislative-settings-panel" onSubmit={save}><section className="cabinet-legislative-config"><LiaGavelSolid /><div><strong>Regras configuráveis da Câmara</strong><p>Defina os tipos de proposição aplicados ao protocolo. Quóruns e modalidades de votação ficam registrados nesta mesma configuração.</p><label>Tipos de proposição<textarea disabled={!canConfigure} value={types} onChange={event => setTypes(event.target.value)} rows="6" /></label><small>Quóruns: {(config.quorums || []).join(', ')} · Votações: {(config.votingTypes || []).join(', ')}.</small></div></section><section className="legislative-settings-card"><h3>Mesa diretora e funções legislativas</h3><p>Selecione vereadores cadastrados para compor a mesa. A secretária legislativa pode cadastrar e publicar atas conforme a permissão atribuída.</p>{canConfigure && <div className="legislative-role-form"><select value={memberId} onChange={event => setMemberId(event.target.value)}><option value="">Selecione o vereador</option>{councilors.map(item => <option key={item.id} value={item.id}>{item.name || item.nome || item.email}</option>)}</select><select value={boardRole} onChange={event => setBoardRole(event.target.value)}>{['Presidente', 'Vice-presidente', '1º Secretário', '2º Secretário', 'Secretária Legislativa', 'Membro da Mesa'].map(value => <option key={value}>{value}</option>)}</select><div className="legislative-permission-checks">{permissionOptions.map(([value, label]) => <label key={value}><input type="checkbox" checked={permissions.includes(value)} onChange={event => setPermissions(event.target.checked ? [...permissions, value] : permissions.filter(item => item !== value))} /> {label}</label>)}</div><button type="button" className="btn-secondary" onClick={assignBoardRole}>Adicionar função</button></div>}<div className="cabinet-list">{(config.boardAssignments || []).map(item => <article className="cabinet-event-row" key={`${item.userId}-${item.role}`}><div><strong>{item.name}</strong><p>{item.role}</p><small>{(item.permissions || []).map(value => permissionOptions.find(option => option[0] === value)?.[1] || value).join(' · ') || 'Permissões próprias da função'}</small></div>{canConfigure && <button type="button" className="btn-secondary" onClick={() => removeBoardRole(item.userId)}>Remover</button>}</article>)}{!(config.boardAssignments || []).length && <p>Nenhuma função definida.</p>}</div></section>{canConfigure && <button className="btn-primary">Salvar configurações e acessos</button>}</form>;
}

