  useEffect(() => { if (!camaraId) return undefined; return onSnapshot(query(collection(firestore, LEGISLATIVE_COLLECTIONS.commissions), where('camaraId', '==', camaraId)), snapshot => setCommissions(snapshot.docs.map(row => ({ id: row.id, ...row.data() }))), error => setFeedback(error.message)); }, [camaraId]);
